import { Show, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { setIri, termOptions, setDisplayedLiteral } from '../../model/edit.js';
import {
  validIriText, termOf as termOfJs, matchesPattern,
} from '../../model/fields.js';
import type { Graph, Quad, Term } from '../../model-boundary.js';
import { graph, graphVersion } from '../../stores/corpus.js';
import {
  editSource, sourceRows, makeEditable,
} from '../../stores/source-management.js';
import type { SourceEdit } from '../../stores/source-management.js';
import { currentLang, text, setNotice } from '../../stores/view.js';
import { ActionStrip, actionState, unlockExplanation } from '../edit/strip.jsx';
import type { IconState } from '../edit/strip.jsx';
import { InlineField, IriCombobox, optionText } from '../edit/field.jsx';
import type { IriOption, FieldHook } from '../edit/field.jsx';
import { LongText } from '../shared/long-text.jsx';
import { FormValues } from './form.jsx';
import type { FormRow } from './form-model.js';
import './form.css';

const core = await import('../../stores/edit.js');
const { execute, editable } = core;

const asTerm = termOfJs as (x: unknown) => Term | null;

interface BareStore { getQuads(s: Term|null, p: Term|null, o: Term|null, g: Term|null): Quad[] }
type Facade = Record<string, unknown>;

const optionsOf = termOptions as unknown as (g: Graph) => Record<string, IriOption[]>;
const writeIri = setIri as unknown as
  (f: Facade, term: string, pred: string, iri: string) => void;
const writeText = setDisplayedLiteral as unknown as (
  f: Facade, readGraph: unknown, term: string, pred: string, value: string,
  defaults?: { lang?: string; datatype?: string },
) => void;

export { matchesPattern };

export function patternGate(row: FormRow, value: string): boolean {
  if (matchesPattern(value, row.pattern)) return true;
  setNotice('edit.invalidPattern', { input: value, field: row.label });
  return false;
}

export function fieldKind(row: FormRow): 'literal' | 'iri' | null {
  if (row.viewer === 'LiteralViewer' || row.viewer === 'LangStringViewer') return 'literal';
  if (row.viewer === 'URIViewer' || row.viewer === 'HyperlinkViewer' || row.viewer === 'LabelViewer') return 'iri';
  const v0 = row.values[0];
  if (!v0) return null;
  return v0.kind === 'text' ? 'literal' : 'iri';
}

function unlockableSource(term: string | null): SourceEdit | null {
  const g = graph() as unknown as BareStore | null;
  if (!g || !term) return null;
  const graphs = new Set(g.getQuads(asTerm(term), null, null, null)
    .map((q) => (q.graph as { value?: string } | undefined)?.value)
    .filter((v): v is string => !!v));
  if (!graphs.size) return null;
  const current = editSource();
  return sourceRows().find((b) => graphs.has(b.graph) && b.graph !== (current ? current.graph : null))
    || null;
}

export default function FormRowEdit(props: {
  row: FormRow;
  term: string | null;
  multiline?: boolean;
}): JSX.Element {
  const row = () => props.row;
  const [hook, setHook] = createSignal<FieldHook | null>(null);
  const [clear, setClear] = createSignal<(() => void) | null>(null);

  const notApplicable = (): string | null => {
    if (row().inverse) return text('edit.fieldReversed');
    if (row().values.length > 1) return text('edit.fieldMultiValued');
    if (!row().path) return text('edit.fieldNoPath');
    return null;
  };
  const kind = () => fieldKind(row());
  const may = () => !notApplicable() && !!props.term && !!kind() && editable(props.term);
  const current = () => row().values[0] || null;

  const plainValue = () => (props.multiline
    ? <LongText text={row().values.map((v) => v.text).join(', ')} />
    : <FormValues row={row()} />);

  const oldText = () => (current() ? current()!.text : '');
  const saveText = (next: string): void => {
    if (String(next) === oldText()) return;
    void execute((f: unknown) => writeText(
      f as Facade, graph(), props.term as string, row().path as string, next,
      { lang: currentLang() },
    ), { group: true });
  };

  const iriOptions = (): IriOption[] => {
    void graphVersion();
    const g = graph() as Graph | null;
    return g ? (optionsOf(g).labeled || []) : [];
  };
  let previous = '';
  const pickIri = (iri: string): void => {
    if (iri && !validIriText(iri)) {
      setNotice('edit.invalidIri', { input: iri });
      return;
    }
    if (iri === previous) return;
    if (!patternGate(row(), iri)) return;
    previous = iri;
    void execute(
      (f: unknown) => writeIri(f as Facade, props.term as string, row().path as string, iri),
      { group: true },
    );
  };

  const clearField = (): void => {
    const g = graph() as unknown as BareStore | null;
    const n = g && props.term && row().path
      ? g.getQuads(asTerm(props.term), asTerm(row().path as string), null, null).length : 0;
    if (n > 1 && !window.confirm(text('edit.fieldClearQuestion'))) return;
    if (kind() === 'iri') {
      void execute(
        (f: unknown) => writeIri(f as Facade, props.term as string, row().path as string, ''),
        { group: true },
      );
      return;
    }
    void execute((f: unknown) => writeText(
      f as Facade, graph(), props.term as string, row().path as string, '',
    ), { group: true });
  };

  const route = () => (notApplicable() || !props.term || editable(props.term)
    ? null : unlockableSource(props.term));
  const onUnlock = () => {
    const b = route();
    if (b) void makeEditable(b).catch(() => {});
  };
  const explanation = () => {
    const b = route();
    return b ? unlockExplanation({
      name: b.name || b.url || '',
      current: editSource()?.name,
      warn: !b.opfs,
    }) : undefined;
  };

  const editState = (): IconState => actionState({
    allow: may(),
    title: text('edit.editField'),
    action: () => hook()?.openEdit(),
    unlockable: !!route(),
    onUnlock: onUnlock,
    unlockExplanation: explanation(),
    notApplicable: notApplicable() || undefined,
  });

  const clearState = (): IconState => actionState({
    allow: may() && !!clear(),
    title: text('edit.clearField'),
    action: () => clear()?.(),
    unlockable: !!route(),
    onUnlock: onUnlock,
    unlockExplanation: explanation(),
    notApplicable: notApplicable() || text('edit.fieldAlreadyEmpty'),
  });

  return (
    <span class="form-row">
      <Show when={may()} fallback={plainValue()}>
        <Show
          when={kind() === 'iri'}
          fallback={(
            <InlineField
              value={oldText()}
              multiline={props.multiline}
              withoutPencil
              validate={(v) => String(v) === oldText() || patternGate(row(), v)}
              onSave={saveText}
              hook={(api) => { setHook(() => api); setClear(() => (oldText() ? clearField : null)); }}
            />
          )}
        >
          <IriCombobox
            options={iriOptions()}
            value={optionText(iriOptions(), current() ? current()!.iri : null)}
            onPick={pickIri}
            hook={(api) => {
              previous = current()?.iri || '';
              setHook(() => api);
              setClear(() => (current()?.iri ? clearField : null));
            }}
          />
        </Show>
      </Show>
      <ActionStrip
        drag={{ on: false, title: text('edit.fieldDragNa') }}
        edit={editState()}
        remove={clearState()}
      />
    </span>
  );
}
